window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"supply":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"供给"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"供应品"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"提供"}],"examples":[{"sentence":"A reliable supply of clean water is essential because it directly affects public health and economic productivity.","translation":"可靠的清洁水供应至关重要，因为它直接影响公共卫生和经济生产力。","targetForm":"supply","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the global supply chain is disrupted, shortages of critical goods can trigger widespread economic instability.","translation":"当全球供应链中断时，关键商品短缺可能引发广泛的经济不稳定。","targetForm":"supply","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Emergency supplies were delivered before nightfall so that families could remain safely inside during the storm.","translation":"应急物资在天黑前送达，使家庭能够在暴风雨期间安全地留在室内。","targetForm":"supplies","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The laboratory supplied each team with identical materials, thereby making the comparison between results more reliable.","translation":"实验室向每个团队提供相同材料，从而使结果之间的比较更可靠。","targetForm":"supplied","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"By supplying detailed evidence, the report enables residents to question how public money is being spent.","translation":"通过提供详细证据，该报告使居民能够质询公共资金的使用方式。","targetForm":"supplying","senseId":"source-v-3","sourceSenseId":"v-3"}]},"surname":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"姓"}],"examples":[{"sentence":"When used as a Chinese surname, the character 林 is pronounced Lín; as a Japanese surname, it is read Hayashi.","translation":"林字作为中国姓氏，就读Lín；作为日本姓氏，则读Hayashi。","targetForm":"surname","senseId":"source-n-1","sourceSenseId":"n-1"}]},"submit":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"提交"}],"examples":[{"sentence":"Before you submit your thesis, ensure that all citations conform to the required academic style guide.","translation":"在提交论文之前，请确保所有引用都符合要求的学术格式指南。","targetForm":"submit","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"To participate in the conference, scholars must submit an abstract that clearly outlines their research question and methodology.","translation":"要参加会议，学者必须提交一份清晰概述其研究问题和方法的摘要。","targetForm":"submit","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The committee requires that all applicants submit their portfolios electronically, which streamlines the evaluation process.","translation":"委员会要求所有申请人以电子方式提交作品集，这简化了评估过程。","targetForm":"submit","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Although the deadline was tight, the team managed to submit a comprehensive grant proposal that secured funding for their research.","translation":"尽管截止日期很紧，团队还是设法提交了一份全面的资助申请，为他们的研究争取到了资金。","targetForm":"submit","senseId":"source-v-4","sourceSenseId":"v-4"}]},"supermarket":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"超级市场"}],"examples":[{"sentence":"If you go to that supermarket, you can buy most things you use in your daily life.","translation":"你去那个超级市场，几乎甚么日用品都买得到。","targetForm":"supermarket","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Since you're going to the supermarket, buy some eggs while you're there.","translation":"既然你要去超市，那就顺便买些鸡蛋吧。","targetForm":"supermarket","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The supermarkets are now closed, so we'll have to make do with what is left in the refrigerator.","translation":"超市现在已经关了，我们只能加减用一下冰箱里剩的食物。","targetForm":"supermarkets","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Starting from 2009, supermarkets and convenience stores have been allowed to sell medicines.","translation":"从2009年开始，超市和便利店就可以出售药品了。","targetForm":"supermarkets","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The old houses were torn down to make room for a supermarket.","translation":"这栋老房子被拆除了，以腾出空间给超级市场。","targetForm":"supermarket","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sunday":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"星期日"}],"examples":[{"sentence":"The outcome of Sunday’s election will determine which way Greece goes – and, also, of course, how the unfolding Greek drama affects the eurozone’s future.","translation":"周日大选的结果将决定希腊走哪条路，当然，也将决定希腊大戏的开展怎样影响欧元区的未来。","targetForm":"sunday","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"CAMBRIDGE – In the French Republican party’s presidential primary on Sunday, François Fillon soundly defeated frontrunner Alain Juppé, winning close to 67% of the votes.","translation":"剑桥 — — 在星期天进行的法国共和党总统初选中，弗朗索瓦·菲永以赢得67%选票的成绩毫无争议地击败了领跑者阿兰·朱佩。","targetForm":"sunday","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although Sunday is typically reserved for rest, many graduate students use it to finalize their research proposals.","translation":"尽管周日通常用于休息，许多研究生却利用这一天来完善他们的研究计划。","targetForm":"sunday","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the library extends its hours on Sunday, scholars can access rare manuscripts that are otherwise unavailable.","translation":"由于图书馆在周日延长开放时间，学者们可以查阅平时无法获取的珍稀手稿。","targetForm":"sunday","senseId":"source-n-1","sourceSenseId":"n-1"}]},"suitable":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"相配的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"适宜的","contextReviewed":true},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"适当的"}],"examples":[{"sentence":"Although the candidate lacked experience, her problem-solving skills made her suitable for the position.","translation":"尽管这位候选人缺乏经验，她解决问题的能力仍使她适合该职位。","targetForm":"suitable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the soil is highly acidic, it is not suitable for most crops without extensive treatment.","translation":"由于土壤酸性很强，若不进行广泛处理，它不适合种植大多数作物。","targetForm":"suitable","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The committee will choose a suitable venue that can accommodate more than five hundred participants.","translation":"委员会将选择能容纳五百多名与会者的合适场地。","targetForm":"suitable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When designing a curriculum, educators must ensure that materials are suitable for varied learning styles.","translation":"设计课程时，教育工作者必须确保教材适合不同的学习风格。","targetForm":"suitable","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"A suitable mentor can accelerate professional growth by providing focused guidance and useful feedback.","translation":"合适的导师能通过提供有针对性的指导和有用反馈，加速职业成长。","targetForm":"suitable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"surge":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"巨涌"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"汹涌"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"电压尖峰","contextReviewed":true}],"examples":[{"sentence":"Although the surge in housing prices limits affordability, it increases the wealth of existing owners.","translation":"尽管房价飙升限制了住房可负担性，它却增加了现有房主的财富。","targetForm":"surge","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A surge in cyberattacks prompted companies to improve security and review their emergency procedures.","translation":"网络攻击激增促使企业加强安全措施并审查应急程序。","targetForm":"surge","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because demand for electric vehicles surged, governments introduced incentives to expand charging networks.","translation":"由于电动汽车需求猛增，政府出台激励措施以扩大充电网络。","targetForm":"surged","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When unemployment surges during a recession, policymakers may support households and retraining programmes.","translation":"当失业率在衰退期激增时，决策者可能支持家庭并提供再培训项目。","targetForm":"surges","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The electrician installed protection that would absorb a voltage surge before it damaged sensitive equipment.","translation":"电工安装了能在电压尖峰损坏敏感设备前吸收它的保护装置。","targetForm":"surge","senseId":"source-other-1","sourceSenseId":"other-1"}]},"sustain":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"继续"}],"examples":[{"sentence":"That said, in such a complex environment, investors can be expected to reach widely disparate conclusions, which will sustain – if not increase – market volatility.","translation":"尽管如此，在如此复杂的环境中，投资者可能形成大相径庭的结论，而这将维持 — — 乃至加剧 — — 市场的波动。","targetForm":"sustain","senseId":"source-v-4","sourceSenseId":"v-4"}]},"suffer":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"受痛苦"}],"examples":[{"sentence":"For ordinary North Koreans, who are suffering the most under the current system, such a transformation could not be more urgent.","translation":"而对那些在当前体制下受苦受难的普通朝鲜人来说，没有比这一转型更迫切的事了。","targetForm":"suffering","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The EU must respond with a genuinely European asylum policy that will put an end to the panic and the unnecessary human suffering.","translation":"欧盟必须应之以能够结束恐慌和不必要的人道灾难的真正的欧洲庇护政策。","targetForm":"suffering","senseId":"source-v-4","sourceSenseId":"v-4"}]},"suite":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"套房"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"(一)套"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"组曲"}],"examples":[{"sentence":"The hotel upgraded us to a luxurious suite with a panoramic view of the coastline.","translation":"酒店将我们升级到一间可俯瞰海岸线全景的豪华套房。","targetForm":"suite","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The executive suite on the top floor includes a private conference room and a lounge area.","translation":"顶层的行政套房包括一间私人会议室和一个休息区。","targetForm":"suite","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The company offers a comprehensive suite of software tools designed for project management.","translation":"该公司提供一套专为项目管理设计的综合软件工具。","targetForm":"suite","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The laboratory purchased a new suite of analytical instruments to enhance research capabilities.","translation":"实验室购买了一套新的分析仪器，以增强研究能力。","targetForm":"suite","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The orchestra performed a Baroque suite that featured elegant dance movements and intricate harmonies.","translation":"管弦乐队演奏了一首巴洛克组曲，其特点是优雅的舞蹈乐章和复杂的和声。","targetForm":"suite","senseId":"source-n-5","sourceSenseId":"n-5"}]},"sum":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"总和"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"金额"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"概要"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"合计"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"概括"}],"examples":[{"sentence":"The accountant confirmed that the sum of all expenses matched the total shown in the annual statement.","translation":"会计确认所有开支的总和与年度报表显示的总额一致。","targetForm":"sum","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The university set aside a substantial sum for laboratory upgrades after several promising projects had been approved.","translation":"数个有前景的项目获批后，大学拨出一大笔资金用于升级实验室。","targetForm":"sum","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"In sum, the review found that the proposal was ambitious but lacked a credible plan for implementation.","translation":"总而言之，审查认为这项提议雄心勃勃，但缺乏可信的实施方案。","targetForm":"sum","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The figures sum to less than the forecast because several departments have not submitted their final invoices.","translation":"这些数字合计低于预测值，因为几个部门尚未提交最终发票。","targetForm":"sum","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"To sum up, the evidence supports early intervention, although it does not justify making the programme compulsory.","translation":"概括来说，证据支持早期干预，但不足以证明该项目应当强制推行。","targetForm":"sum","senseId":"source-v-2","sourceSenseId":"v-2"}]},"surprise":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"惊奇"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"奇袭"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使惊奇"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"撞见"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"奇袭"}],"examples":[{"sentence":"To the surprise of the research team, the result contradicted the hypothesis that had guided the entire experiment.","translation":"令研究团队惊讶的是，结果与指导整个实验的假设相矛盾。","targetForm":"surprise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The patrol avoided a surprise attack by changing its route after receiving a reliable warning.","translation":"巡逻队收到可靠警报后改变路线，避开了一次突然袭击。","targetForm":"surprise","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"It surprised the editor that readers responded most strongly to the shortest and least dramatic article.","translation":"令编辑惊奇的是，读者对最短且最不戏剧化的文章反应最强烈。","targetForm":"surprised","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The inspector surprised several workers by arriving before dawn, when the site was usually quiet.","translation":"检查员在黎明前到达，撞见了几名工人，因为这时工地通常很安静。","targetForm":"surprised","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The small force surprised the guard post at night, although the operation was later criticised as unnecessarily risky.","translation":"这支小部队夜间突袭了哨所，尽管该行动后来被批评为冒险过度。","targetForm":"surprised","senseId":"source-v-3","sourceSenseId":"v-3"}]},"susceptible":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"易受影响的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"容许...的"}],"examples":[{"sentence":"Young children are particularly susceptible to viral infections during the winter months.","translation":"年幼的儿童在冬季特别容易受到病毒感染。","targetForm":"susceptible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The coastal ecosystem is highly susceptible to damage from rising sea levels and pollution.","translation":"沿海生态系统极易受到海平面上升和污染的损害。","targetForm":"susceptible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"She was susceptible to flattery, which made her an easy target for manipulative colleagues.","translation":"她容易受奉承话的影响，这使她成为善于操纵的同事的轻易目标。","targetForm":"susceptible","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The new policy is susceptible of multiple interpretations, leading to confusion among the staff.","translation":"新政策容许有多种解释，导致员工之间产生困惑。","targetForm":"susceptible","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"This complex theory is susceptible to simplification if we focus only on its core principles.","translation":"如果我们只关注其核心原则，这个复杂的理论是可以被简化的。","targetForm":"susceptible","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"sugar":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"糖"}],"examples":[{"sentence":"Plants produce sugar through photosynthesis, converting sunlight into chemical energy that sustains nearly all life on Earth.","translation":"植物通过光合作用产生糖分，将阳光转化为化学能，维持了地球上几乎所有的生命。","targetForm":"sugar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Many processed foods contain hidden sugar, which makes it difficult for consumers to control their intake unless they carefully read nutrition labels.","translation":"许多加工食品含有隐藏的糖分，这使得消费者难以控制摄入量，除非他们仔细阅读营养标签。","targetForm":"sugar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The government imposed a tax on sugary drinks to discourage excessive sugar consumption, a policy that has proven effective in several countries.","translation":"政府对含糖饮料征税，以抑制过量糖分摄入，这一政策已在多个国家被证明有效。","targetForm":"sugar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chef added a pinch of sugar to the tomato sauce to balance the acidity, thereby enhancing the overall flavor of the dish.","translation":"厨师在番茄酱中加入少许糖以平衡酸度，从而提升了菜肴的整体风味。","targetForm":"sugar","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Excessive consumption of sugar has been linked to a higher risk of obesity and diabetes, which has prompted many governments to introduce health campaigns.","translation":"过量摄入糖分与肥胖和糖尿病的较高风险有关，这促使许多政府推出了健康宣传活动。","targetForm":"sugar","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sue":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"提出诉讼"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"起诉"}],"examples":[{"sentence":"Meanwhile, in 2001, taking advantage of the USPTO’s slow response, Proctor sued 16 small seed companies in Colorado for patent-infringement.","translation":"与此同时，2001年，利用美国专利商标局反应慢的弱点，Proctor对科罗拉多州16家小型种子公司提出侵犯专利权的诉讼。","targetForm":"sued","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Environmental groups often sue corporations that violate pollution laws, thereby holding them accountable for ecological damage.","translation":"环保组织经常起诉违反污染法的企业，从而使它们对生态破坏负责。","targetForm":"sue","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"If the manufacturer fails to recall the defective product, consumers may sue for compensation to cover medical expenses.","translation":"如果制造商未能召回有缺陷的产品，消费者可以提起诉讼要求赔偿以支付医疗费用。","targetForm":"sue","senseId":"source-v-4","sourceSenseId":"v-4"}]},"sun":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"太阳"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"阳光"}],"examples":[{"sentence":"The sun's gravitational pull keeps the planets in orbit, a fact that has fascinated astronomers for centuries.","translation":"太阳的引力使行星保持在轨道上，这一事实数百年来一直令天文学家着迷。","targetForm":"sun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the sun rose on the final day of the expedition, the team recorded every instrument reading before packing the field station.","translation":"考察最后一天太阳升起时，团队在收拾野外站点前记录了每台仪器的读数。","targetForm":"sun","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the room faced north, a strip of afternoon sun reached the desk through the narrow window.","translation":"尽管房间朝北，午后的阳光仍透过狭窄的窗户照到书桌上。","targetForm":"sun","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The farmers spread the herbs in the sun so that they would dry naturally without losing their fragrance.","translation":"农民把香草铺在阳光下晒干，以便它们自然干燥而不失香味。","targetForm":"sun","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Before the ceremony, guests sat in the warm sun and watched the river change colour near sunset.","translation":"仪式开始前，宾客们坐在温暖的阳光下，看着河水在日落前变换颜色。","targetForm":"sun","senseId":"source-n-4","sourceSenseId":"n-4"}]},"surroundings":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"环境"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"周围的事物"}],"examples":[{"sentence":"The architect designed the building to harmonize with its natural surroundings, incorporating local stone and native plants.","translation":"建筑师设计这座建筑时使其与自然环境相协调，采用了当地石材和本土植物。","targetForm":"surroundings","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She found it difficult to concentrate in her new surroundings because the constant noise from the nearby construction site was distracting.","translation":"她发现在新环境中很难集中注意力，因为附近建筑工地的持续噪音令人分心。","targetForm":"surroundings","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chameleon changes color to blend into its surroundings, which helps it avoid predators and ambush prey.","translation":"变色龙改变颜色以融入周围环境，这有助于它躲避捕食者和伏击猎物。","targetForm":"surroundings","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"After years of living in the bustling city, he appreciated the peace of his rural surroundings, where the only sounds were birdsong and rustling leaves.","translation":"在喧嚣的城市生活多年后，他欣赏乡村环境的宁静，那里唯一的声音是鸟鸣和树叶沙沙作响。","targetForm":"surroundings","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The laboratory maintains sterile surroundings to prevent contamination of the sensitive experiments conducted there.","translation":"实验室保持无菌环境，以防止在那里进行的敏感实验受到污染。","targetForm":"surroundings","senseId":"source-n-1","sourceSenseId":"n-1"}]},"superb":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"极好的"}],"examples":[{"sentence":"The museum's superb lighting allowed visitors to examine small details without damaging the paintings.","translation":"博物馆出色的照明让访客能观察细节，同时不损害画作。","targetForm":"superb","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Although the ingredients were simple, the chef produced a superb meal through careful preparation.","translation":"尽管食材简单，厨师仍通过精心准备做出了一顿极好的饭菜。","targetForm":"superb","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Because the guide gave a superb explanation, the group understood why the site required protection.","translation":"由于向导作了精彩解释，团队理解了该地点为何需要保护。","targetForm":"superb","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The orchestra delivered a superb performance when it returned to the city after a long tour.","translation":"管弦乐团结束长期巡演回到这座城市时，奉献了一场极好的演出。","targetForm":"superb","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Although the task was challenging, her superb attention to detail prevented several costly errors.","translation":"尽管任务富有挑战，她出色的细节关注避免了几项代价高昂的错误。","targetForm":"superb","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"suspicious":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"怀疑的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"可疑的"}],"examples":[{"sentence":"The auditor became suspicious when several invoices lacked proper documentation, which suggested a possible breach of protocol.","translation":"审计员发现多张发票缺少适当凭证时起了疑心，这表明可能存在违规行为。","targetForm":"suspicious","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The public remains suspicious of claims that the new policy will reduce inequality, given the lack of transparent implementation plans.","translation":"鉴于缺乏透明的实施计划，公众仍然怀疑新政策能减少不平等这一说法。","targetForm":"suspicious","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Although the transaction appeared legitimate, the bank flagged it as suspicious because the amount deviated significantly from the customer's usual pattern.","translation":"尽管交易看似合法，但银行因其金额明显偏离客户惯常模式而将其标记为可疑。","targetForm":"suspicious","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"success":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"成功"}],"examples":[{"sentence":"Certainly, coordination between the member states exists, and is even successful at times, but without strong European institutions, such singular successes will not last.","translation":"当然，成员国之间的协调是存在的，有时甚至是成功的，但没有强大的欧洲机构，单个的成功将不会持续太久。","targetForm":"successes","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sufficient":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"足够的"}],"examples":[{"sentence":"But the new guidelines are not sufficient to guarantee such an outcome.","translation":"但新意见不足以保证这样的结果。","targetForm":"sufficient","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"succeed":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"成功"}],"examples":[{"sentence":"History suggests that collective negotiation about currencies and a new approach to the issue of reserves are unlikely to succeed.","translation":"历史似乎意味着，有关汇率和储备问题新方案的会谈是不太可能成功的。","targetForm":"succeed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"substance":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"物质"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"实质"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"资产"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"本质"}],"examples":[{"sentence":"The laboratory labelled each substance clearly so that students could identify materials safely during the lesson.","translation":"实验室清楚标记每种物质，让学生能在课堂中安全识别材料。","targetForm":"substance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the speech was polished, it lacked substance and did not answer the main question.","translation":"尽管演讲很有文采，它却缺乏实质内容，也没有回答主要问题。","targetForm":"substance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the committee examined the substance of the proposal, it found that several costs had been omitted.","translation":"当委员会审查提案实质时，发现几项成本被遗漏了。","targetForm":"substance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the family's substance had grown through careful saving, they could support the local project.","translation":"由于这个家庭通过谨慎储蓄积累了资产，他们能够支持当地项目。","targetForm":"substance","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The book explores the substance of friendship rather than merely describing pleasant social occasions.","translation":"这本书探讨友谊的本质，而不只是描写愉快的社交场合。","targetForm":"substance","senseId":"source-n-5","sourceSenseId":"n-5"}]},"surface":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"表面"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"水面"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"外表"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"表面的"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"呈现"}],"examples":[{"sentence":"Although the table's surface looked polished, a closer inspection revealed fine scratches left by repeated use.","translation":"尽管桌面看上去已抛光，仔细检查仍发现反复使用留下的细小划痕。","targetForm":"surface","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"At sunrise, mist drifted across the surface of the lake, where fishing boats had already begun to move.","translation":"日出时，薄雾掠过湖面，渔船已经开始行驶。","targetForm":"surface","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Beneath the surface of the celebration, several partners remained uncertain about whether the agreement could be funded.","translation":"在庆祝的表象之下，几位合作方仍不确定该协议能否获得资金支持。","targetForm":"surface","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The two schemes share surface similarities, but their assumptions about who bears the cost are fundamentally different.","translation":"两项方案在表面上相似，但对于谁承担成本的假设根本不同。","targetForm":"surface","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"As more records were released, evidence of earlier warnings began to surface in the public inquiry.","translation":"随着更多记录被公开，早期预警的证据开始在公开调查中浮现。","targetForm":"surface","senseId":"source-v-4","sourceSenseId":"v-4"}]},"surgeon":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"外科医生"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"军医"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"船医"}],"examples":[{"sentence":"Before the operation, the surgeon reviewed the imaging with the wider team so that each stage could be anticipated.","translation":"手术前，外科医生与整个团队复核影像资料，以便预先考虑每个步骤。","targetForm":"surgeon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The surgeon explained the procedure in plain language, allowing the family to ask questions without feeling rushed.","translation":"外科医生用通俗语言说明了手术过程，让家属可以从容提问。","targetForm":"surgeon","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the field exercise, the military surgeon coordinated with medics who were responsible for transporting casualties safely.","translation":"野外演练期间，军医与负责安全转运伤员的医护人员协调工作。","targetForm":"surgeon","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The ship's surgeon organised the medical supplies before departure, because the vessel would be far from the nearest port.","translation":"由于船只将远离最近港口，船医在出发前整理了医疗物资。","targetForm":"surgeon","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although the surgeon had extensive technical expertise, colleagues valued her equally for the calm way she led difficult conversations.","translation":"尽管这位外科医生技术经验丰富，同事同样重视她冷静主持艰难沟通的方式。","targetForm":"surgeon","senseId":"source-n-1","sourceSenseId":"n-1"}]},"superfluous":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"多余的"}],"examples":[{"sentence":"Although the proposal was sound, its superfluous annexes obscured the central argument for many readers.","translation":"尽管提案本身合理，但多余的附件掩盖了核心论点，使许多读者难以把握重点。","targetForm":"superfluous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The curator removed superfluous labels so that visitors could examine the paintings without distraction.","translation":"策展人撤去了多余的说明牌，以便参观者能够不受干扰地欣赏画作。","targetForm":"superfluous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the laboratory already owned the equipment, purchasing another set would have been superfluous.","translation":"由于实验室已经拥有这套设备，再购买一套就显得多余了。","targetForm":"superfluous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A concise conclusion is often stronger than a superfluous summary that merely repeats the preceding evidence.","translation":"简洁的结论往往比只重复前文证据的冗余总结更有力。","targetForm":"superfluous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Without superfluous packaging, the company reduced both shipping costs and the material it sent to landfill.","translation":"去除多余包装后，这家公司同时降低了运输成本和送往填埋场的材料量。","targetForm":"superfluous","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"suicide":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"自杀"}],"examples":[{"sentence":"Researchers have found that prolonged economic hardship can significantly increase the risk of suicide, especially among middle-aged men.","translation":"研究人员发现，长期的经济困难会显着增加自杀风险，尤其是在中年男性中。","targetForm":"suicide","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although suicide is often linked to depression, not everyone who takes their own life has a diagnosed mental illness.","translation":"尽管自杀常与抑郁症相关，但并非每个结束自己生命的人都患有确诊的精神疾病。","targetForm":"suicide","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because suicide can have a profound impact on families and communities, postvention support is just as important as prevention.","translation":"由于自杀会对家庭和社区产生深远影响，事后干预支持与预防同样重要。","targetForm":"suicide","senseId":"source-n-1","sourceSenseId":"n-1"}]},"submerge":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"淹没"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使浸水"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使陷入"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"潜入水中"}],"examples":[{"sentence":"When the tide rises, seawater can submerge the narrow causeway and delay deliveries to the island.","translation":"涨潮时，海水会淹没狭窄堤道，使向岛上配送物资延误。","targetForm":"submerge","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The technician submerged the sensor in water to test whether its protective seal would remain effective.","translation":"技术员把传感器浸入水中，以测试它的保护密封是否仍然有效。","targetForm":"submerged","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the message was important, it became submerged beneath a stream of less relevant notifications.","translation":"尽管这条信息很重要，它还是被一连串不太相关的通知淹没了。","targetForm":"submerged","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The archivist refused to submerge the local history beneath a simplified narrative designed only for tourists.","translation":"档案员拒绝把地方历史埋没在仅为游客设计的简化叙述之下。","targetForm":"submerge","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"To inspect the reef without disturbing it, the researchers allowed the small vehicle to submerge slowly below the surface.","translation":"为在不扰动礁石的情况下检查它，研究人员让小型设备缓慢下潜到水面以下。","targetForm":"submerge","senseId":"source-v-4","sourceSenseId":"v-4"}]},"sunrise":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"日出"}],"examples":[{"sentence":"Although the sunrise symbolizes new beginnings, it also reminds us that each day brings its own challenges.","translation":"尽管日出象征着新的开始，但它也提醒我们每一天都会带来自己的挑战。","targetForm":"sunrise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The photographer captured the sunrise from the mountain peak, which required a strenuous hike that began at midnight.","translation":"摄影师从山顶捕捉到了日出，这需要从午夜开始的艰苦徒步。","targetForm":"sunrise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the sunrise over the ocean was particularly stunning, the couple decided to extend their vacation by another day.","translation":"由于海上的日出特别壮观，这对夫妇决定将假期再延长一天。","targetForm":"sunrise","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the first rays of sunrise illuminated the ancient ruins, the archaeologists felt a deep connection to the civilization that once thrived there.","translation":"当日出的第一缕阳光照亮古代遗址时，考古学家们对曾经在那里繁荣的文明产生了深刻的联系。","targetForm":"sunrise","senseId":"source-n-1","sourceSenseId":"n-1"}]},"survive":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"比...活得长"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"生存"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"幸存"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"幸免于"}],"examples":[{"sentence":"The founder survived several early partners and eventually saw the small workshop become a national business.","translation":"创始人比几位早期合伙人活得更久，最终看到小作坊发展成全国性企业。","targetForm":"survived","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the first season was difficult, the local theatre survived by sharing staff and equipment with nearby schools.","translation":"尽管第一个演出季很艰难，当地剧院通过与附近学校共用人员和设备得以维持。","targetForm":"survived","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Traditional songs survive when younger performers learn not only the words but also the stories behind them.","translation":"当年轻表演者不仅学习歌词，也了解其背后的故事时，传统歌曲就能流传下来。","targetForm":"survive","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"The old stone bridge survived the winter floods because its arches allowed water to pass beneath safely.","translation":"这座古老石桥之所以挺过冬季洪水，是因为拱形结构让水能安全从下方通过。","targetForm":"survived","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Without reliable records, few details about the early settlement would survive for future historians to examine.","translation":"没有可靠记录，早期定居点的细节很少能留存下来供后来的历史学家考察。","targetForm":"survive","senseId":"source-v-6","sourceSenseId":"v-6"}]},"sunset":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"日落"}],"examples":[{"sentence":"Even after sunset there was little moderation in the temperature.","translation":"甚至在日落之后，气温也不见降低。","targetForm":"sunset","senseId":"source-n-1","sourceSenseId":"n-1"}]},"superiority":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"优越"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"高傲"}],"examples":[{"sentence":"Although some educators claim the superiority of traditional lectures, interactive methods often lead to deeper understanding.","translation":"尽管一些教育工作者声称传统讲座的优越性，但互动式方法往往能带来更深刻的理解。","targetForm":"superiority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"His air of superiority alienated his colleagues, which ultimately hindered collaboration and slowed the project's progress.","translation":"他的优越感使同事们疏远，最终阻碍了合作并减缓了项目进展。","targetForm":"superiority","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"To demonstrate the superiority of their new drug, the researchers conducted a double-blind trial, thereby providing robust evidence.","translation":"为了证明其新药的优越性，研究人员进行了双盲试验，从而提供了有力的证据。","targetForm":"superiority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's technological superiority in battery design has allowed it to dominate the electric vehicle market, which is rapidly expanding.","translation":"该公司在电池设计方面的技术优势使其主导了快速扩张的电动汽车市场。","targetForm":"superiority","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The debate over the superiority of renewable energy over fossil fuels is central to climate policy, because it affects investment decisions.","translation":"关于可再生能源相对于化石燃料的优越性的辩论是气候政策的核心，因为它影响投资决策。","targetForm":"superiority","senseId":"source-n-1","sourceSenseId":"n-1"}]},"successor":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"接任者"}],"examples":[{"sentence":"Their loss is Myanmar/Burma’s – and South Asia’s – gain, regardless of what Thein or his democratically chosen successors choose to call their country.","translation":"而中国人的损失就是缅甸及南亚的所得，无论登盛或在其之后民主选举出来的后继者选择如何称呼自己的国家。","targetForm":"successors","senseId":"source-n-2","sourceSenseId":"n-2"}]},"superficial":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"表面的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"肤浅的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"面积的"}],"examples":[{"sentence":"The damage appeared superficial, but engineers still inspected the structure to ensure that no hidden supports had shifted.","translation":"损坏看似表面化，但工程师仍检查了结构，以确保没有隐藏支撑发生移位。","targetForm":"superficial","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the article was polished, its argument remained superficial because it never explained how the evidence had been selected.","translation":"尽管文章写得精致，论证仍显肤浅，因为从未解释证据如何被选择。","targetForm":"superficial","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A superficial reading of the statistics can be misleading when averages conceal major differences between neighbourhoods.","translation":"当平均数掩盖社区间重大差异时，对统计数据的肤浅阅读会产生误导。","targetForm":"superficial","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The report recorded the superficial area affected by the fire, which helped planners estimate the scale of restoration needed.","translation":"报告记录了火灾影响的表层面积，这帮助规划人员估计所需修复规模。","targetForm":"superficial","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The two designs share superficial similarities, while their assumptions about cost and access are entirely different.","translation":"两种设计在表面上相似，但对成本和可达性的假设完全不同。","targetForm":"superficial","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"superstition":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"迷信"}],"examples":[{"sentence":"Superstition can persist when people confuse a memorable coincidence with evidence of a reliable cause.","translation":"当人们把难忘的巧合误认为可靠原因的证据时，迷信就可能持续存在。","targetForm":"superstition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the superstition was harmless in this case, the teacher used it to discuss how claims should be tested.","translation":"尽管这次迷信本身无害，老师仍借此讨论观点应如何被检验。","targetForm":"superstition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The exhibition compared local superstition with the scientific explanations that later changed everyday practices.","translation":"展览比较了当地迷信与后来改变日常习惯的科学解释。","targetForm":"superstition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because superstition often offers a quick explanation, it may feel persuasive before people examine the available evidence.","translation":"由于迷信常提供快速解释，人们在审视现有证据前可能觉得它很有说服力。","targetForm":"superstition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The writer treated superstition respectfully as cultural history while making clear that it was not a basis for decisions.","translation":"作者把迷信作为文化历史予以尊重地对待，同时明确它不是作决定的依据。","targetForm":"superstition","senseId":"source-n-1","sourceSenseId":"n-1"}]},"surgery":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"外科"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"手术"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"手术室"}],"examples":[{"sentence":"The university introduced a course in surgery that focused on teamwork, ethics, and the history of the field.","translation":"大学开设了一门外科学课程，重点讨论团队协作、伦理以及该领域的历史。","targetForm":"surgery","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The hospital's annual report described how surgery schedules were coordinated with laboratory, transport, and recovery teams.","translation":"医院年度报告说明了如何协调手术安排与实验室、转运及恢复团队。","targetForm":"surgery","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the surgery suite was modernised, the architects preserved a quiet waiting area for families and staff.","translation":"尽管手术室套间进行了现代化改造，建筑师仍保留了供家属和员工使用的安静等候区。","targetForm":"surgery","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The archive contains a nineteenth-century account of surgery, showing how professional standards changed over time.","translation":"档案馆保存着一份十九世纪的外科学记录，展示专业标准如何随时间变化。","targetForm":"surgery","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The hospital published a glossary that distinguished surgery from other departments for visitors navigating the building.","translation":"医院发布了一份词汇表，为在楼内寻找地点的访客区分外科与其他科室。","targetForm":"surgery","senseId":"source-n-1","sourceSenseId":"n-1"}]},"suspect":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"被怀疑者"}],"examples":[{"sentence":"I suspect that they water down the beer in that pub.","translation":"我怀疑那家酒馆的啤酒兑水了。","targetForm":"suspect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I suspect that Tom will never agree to do that.","translation":"我怀疑汤姆永远不会同意那样做。","targetForm":"suspect","senseId":"source-n-1","sourceSenseId":"n-1"}]},"suspend":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"吊"},{"id":"source-v-7","partOfSpeech":"v.","sourceSenseIds":["v-7"],"sense":"悬浮"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"暂停"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"停止偿付债务"}],"examples":[{"sentence":"The designers suspended a large model from the ceiling so that visitors could walk underneath and inspect it closely.","translation":"设计人员把大型模型悬挂在天花板上，让访客可以从下方走过并近距离观察。","targetForm":"suspended","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"A fine mist suspended in the air made the sunlight visible as it entered through the high windows.","translation":"悬浮在空气中的细雾让从高窗射入的阳光变得可见。","targetForm":"suspended","senseId":"source-v-7","sourceSenseId":"v-7"},{"sentence":"Although the service was suspended for repairs, the library arranged a temporary collection point nearby.","translation":"尽管服务因维修暂停，图书馆仍在附近安排了临时取书点。","targetForm":"suspended","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The committee agreed to suspend the vote until every member had received the revised financial documents.","translation":"委员会同意暂停投票，直到每位成员收到修订后的财务文件。","targetForm":"suspend","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The company had to suspend payments briefly while its accounts were independently reviewed and corrected.","translation":"公司在账目接受独立审查和更正期间，不得不暂时停止付款。","targetForm":"suspend","senseId":"source-v-8","sourceSenseId":"v-8"}]},"subscribe":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"捐款"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"签署"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"赞成"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"预订"}],"examples":[{"sentence":"Several former students subscribed to the scholarship fund so that local applicants could receive travel support.","translation":"几位校友向奖学金基金捐款，以便当地申请者获得出行支持。","targetForm":"subscribed","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"Before the exhibition opened, supporters subscribed their names to a statement asking the council to preserve the building.","translation":"展览开放前，支持者在请求市政部门保护建筑的声明上签署了姓名。","targetForm":"subscribed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although she does not subscribe to every claim in the book, she values its careful use of historical evidence.","translation":"尽管她不赞同书中的每一项论断，她仍重视它对历史证据的谨慎使用。","targetForm":"subscribe","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The library subscribed to a digital archive, thereby allowing students to consult newspapers from earlier centuries.","translation":"图书馆订阅了数字档案，使学生能查阅早期世纪的报纸。","targetForm":"subscribed","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"To subscribe to the journal, readers select a print or digital plan and confirm the delivery address.","translation":"要订阅这本期刊，读者选择纸质或数字方案并确认寄送地址。","targetForm":"subscribe","senseId":"source-v-6","sourceSenseId":"v-6"}]},"suggest":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"建议"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"暗示"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"使人想起"}],"examples":[{"sentence":"The chair suggested a shorter agenda so that the group could spend more time on the unresolved question.","translation":"主席建议使用更短的议程，以便小组能把更多时间用在尚未解决的问题上。","targetForm":"suggested","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Before printing the guide, the editor suggested adding a map for visitors who were unfamiliar with the area.","translation":"印刷指南前，编辑建议增加一张地图，供不熟悉该地区的访客使用。","targetForm":"suggested","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The results suggest that the new timetable reduced waiting times, although more observations are still needed.","translation":"结果表明新时间表缩短了等待时间，尽管仍需要更多观察数据。","targetForm":"suggest","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The uneven wear on the steps suggested that the original entrance had been used far more heavily than expected.","translation":"台阶不均匀的磨损暗示原始入口的使用频率远高于预期。","targetForm":"suggested","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The old photograph suggested a story about the neighbourhood that later inspired the students' exhibition project.","translation":"这张旧照片让人想到一个关于社区的故事，后来启发了学生的展览项目。","targetForm":"suggested","senseId":"source-v-6","sourceSenseId":"v-6"}]},"suppress":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"镇压"},{"id":"source-v-7","partOfSpeech":"v.","sourceSenseIds":["v-7"],"sense":"平定","contextReviewed":true},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"抑制"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"查禁"}],"examples":[{"sentence":"The historian argued that attempts to suppress peaceful dissent often create deeper resentment rather than lasting stability.","translation":"历史学家认为，试图镇压和平的异议往往会造成更深的怨恨，而非持久稳定。","targetForm":"suppress","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the authorities suppressed the immediate disturbance, they did not address the conditions that had caused it.","translation":"尽管当局平息了眼前的骚乱，他们并未解决引发它的条件。","targetForm":"suppressed","senseId":"source-v-7","sourceSenseId":"v-7"},{"sentence":"The software can suppress background noise so that online discussions remain clear even in a busy office.","translation":"该软件可以抑制背景噪音，使线上讨论即使在繁忙办公室里仍清晰可听。","targetForm":"suppress","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Rather than suppressing every doubt, the researcher recorded the uncertainties and explained how later tests could resolve them.","translation":"研究人员没有压制所有疑问，而是记录不确定性并说明后续测试如何解决它们。","targetForm":"suppressing","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The court ruled that officials could not suppress the report merely because its conclusions were politically inconvenient.","translation":"法院裁定，官员不能仅因报告结论在政治上令人不便就查禁该报告。","targetForm":"suppress","senseId":"source-v-5","sourceSenseId":"v-5"}]},"subsequent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"后来的"}],"examples":[{"sentence":"This sketch of the crisis highlights how much has changed over the subsequent 20 years.","translation":"这一危机速写突显出此后20年所发生的巨大的变化。","targetForm":"subsequent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"suffice":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"足够"}],"examples":[{"sentence":"Altogether, this does not seem to require a major increase in the Union’s resources: 1% of aggregate GDP would suffice to perform these tasks.","translation":"总体来说，这看起来并不苛求欧盟资源巨幅增长：共同GDP的1%足以完成这些任务了。","targetForm":"suffice","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"A brief summary will suffice to convey the main findings, provided that the key data points are clearly highlighted.","translation":"只要关键数据点被清晰突出，一个简短的摘要就足以传达主要发现。","targetForm":"suffice","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although basic computer skills suffice for routine tasks, more complex projects demand specialized technical knowledge.","translation":"尽管基本的计算机技能足以应对常规任务，但更复杂的项目需要专门的技术知识。","targetForm":"suffice","senseId":"source-v-1","sourceSenseId":"v-1"}]},"surround":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"包围"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"环绕"}],"examples":[{"sentence":"To strengthen his position, Tom surrounded himself with intellectuals and church dignitaries, one of whom was Brother John.","translation":"为了巩固自己的地位，汤姆身边聚集了一群知识分子和教会要员，其中一位就是约翰弟兄。","targetForm":"surrounded","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The Chinese mainland's coasts are surrounded by the Bohai sea, the Yellow Sea, the East China sea and the South China sea.","translation":"中国大陆的沿海有渤海，黄海，东海和南海。","targetForm":"surrounded","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Japan is a country surrounded by the sea on all sides.","translation":"日本是个四面环海的国家。","targetForm":"surrounded","senseId":"source-v-2","sourceSenseId":"v-2"}]},"successful":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"成功的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"顺利的"}],"examples":[{"sentence":"The project was successful because the team tested the service with users before spending money on a larger launch.","translation":"该项目之所以成功，是因为团队在投入更多资金推广前先与用户测试了服务。","targetForm":"successful","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the first event was small, it was successful enough to persuade local businesses to support a second one.","translation":"尽管首场活动规模很小，它仍足够成功，说服了本地企业支持第二场。","targetForm":"successful","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A successful essay develops one clear argument and uses examples that genuinely support each stage of reasoning.","translation":"一篇成功的文章展开一个清晰论点，并使用真正支持每一步推理的例子。","targetForm":"successful","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The negotiation became successful only after both sides agreed to discuss evidence before making further demands.","translation":"双方同意在提出更多要求前讨论证据后，谈判才变得顺利。","targetForm":"successful","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Because the restoration was successful, the library could reopen the reading room without removing its historic features.","translation":"由于修复顺利，图书馆无需拆除历史特色就能重新开放阅览室。","targetForm":"successful","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"sudden":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"突然的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"意外的"}],"examples":[{"sentence":"A sudden change in wind forced the crew to postpone the outdoor recording until the equipment could be secured.","translation":"风向突然变化迫使工作人员推迟户外录制，直到设备可以固定好。","targetForm":"sudden","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the announcement was sudden, the organisation had prepared a clear explanation for employees and clients.","translation":"尽管公告来得突然，该组织仍为员工和客户准备了清晰说明。","targetForm":"sudden","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The sudden rise in demand revealed weaknesses in the supply system that had not been visible before.","translation":"需求突然上升暴露了供应体系中此前并不明显的弱点。","targetForm":"sudden","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When the lights failed without warning, the sudden darkness made the audience remain seated until staff arrived.","translation":"灯光毫无预警地熄灭时，突如其来的黑暗使观众留在座位上，直到工作人员到来。","targetForm":"sudden","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the sudden departure left a gap in the schedule, the coordinator asked another speaker to take the final session.","translation":"由于突然离开造成日程空缺，协调员请另一位演讲者承担最后一场。","targetForm":"sudden","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"summon":{"senseGroups":[{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"传讯","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"召唤"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"召集"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"鼓起"}],"examples":[{"sentence":"Although the evidence was weak, the prosecutor decided to summon the key witness to strengthen the case.","translation":"尽管证据薄弱，检察官还是决定传唤关键证人以加强案情。","targetForm":"summon","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"The ancient ritual was believed to summon ancestral spirits, which would then offer guidance to the community.","translation":"人们相信这个古老的仪式能召唤祖先的灵魂，然后为社区提供指引。","targetForm":"summon","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The board of directors can summon an extraordinary general meeting if a majority of shareholders request it.","translation":"如果多数股东要求，董事会可以召集临时股东大会。","targetForm":"summon","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because the situation required immediate action, the team leader had to summon all her resolve to make a difficult decision.","translation":"由于情况需要立即行动，团队领导不得不鼓起全部决心做出艰难的决定。","targetForm":"summon","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"When the ambassador was declared persona non grata, the foreign ministry had to summon the envoy to convey the decision.","translation":"当大使被宣布为不受欢迎的人时，外交部不得不召见特使以传达这一决定。","targetForm":"summon","senseId":"source-v-1","sourceSenseId":"v-1"}]},"surpass":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"凌驾"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"超越"}],"examples":[{"sentence":"The reason the Northern and Southern Dynasties had failed in their rule was that they allowed literary splendor to surpass real substance.","translation":"南北朝在他们的统治之下失败了的原因是他们让文学的光辉超越了实质内容。","targetForm":"surpass","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"However, other aspects have already surpassed the standards of many Western countries.","translation":"不过，其它的方面已经超过了很多西方国家的程度。","targetForm":"surpassed","senseId":"source-v-1","sourceSenseId":"v-1"}]},"suck":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"吸"}],"examples":[{"sentence":"I sucked up the dust on the floor with a vacuum cleaner.","translation":"我用吸尘机把地上的灰尘吸掉了。","targetForm":"sucked","senseId":"source-v-1","sourceSenseId":"v-1"}]},"subway":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"地铁"}],"examples":[{"sentence":"In London, the police are always worried about finding a bomb on the train or subway.","translation":"在伦敦，警察总是担心在列车或地铁上发现炸弹。","targetForm":"subway","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It only takes 20 minutes to get to school by the newly opened subway.","translation":"坐新开的地铁上学只需要 20 分钟。","targetForm":"subway","senseId":"source-n-1","sourceSenseId":"n-1"}]},"submarine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"潜水艇"}],"examples":[{"sentence":"Russia is sending battleships, marines, and landing craft tanks against Syria, and submarine equiment against Iran.","translation":"俄罗斯正向叙利亚派遣战舰、海军陆战队和登陆艇坦克，并向伊朗派遣潜舰装备。","targetForm":"submarine","senseId":"source-n-1","sourceSenseId":"n-1"}]},"surplus":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"盈余"}],"examples":[{"sentence":"Our surplus has swelled by nearly ten percent in this quarter.","translation":"我们公司今季的赤字上涨了差不多一成。","targetForm":"surplus","senseId":"source-n-3","sourceSenseId":"n-3"}]},"survival":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"生存"}],"examples":[{"sentence":"This medicine will increase the survival rate of the patients.","translation":"这个药品会提高病人的存活率。","targetForm":"survival","senseId":"source-n-1","sourceSenseId":"n-1"}]},"supper":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"晚餐"}],"examples":[{"sentence":"You can't get in without your key anyway, so you may as well come to have supper with us.","translation":"没有你的钥匙的话，你还是进不去，所以你不放来跟我们一起吃晚饭。","targetForm":"supper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I don't eat supper because I want to lose some weight.","translation":"我不吃晚饭因为我想减肥。","targetForm":"supper","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"You should apologize to Dad for not coming home in time for supper.","translation":"你应该为你没有及时回家吃晚餐向你父亲道歉。","targetForm":"supper","senseId":"source-n-1","sourceSenseId":"n-1"}]},"survey":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"调查"}],"examples":[{"sentence":"This commentary is based on the just-released Economic Survey of India.","translation":"本评论基于刚刚发布的《印度经济调查 》 。","targetForm":"survey","senseId":"source-n-5","sourceSenseId":"n-5"}]},"superior":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"占优势的人"}],"examples":[{"sentence":"This modern, progressive, and peaceful model is unique and superior to all other currently available approaches to the fundamental questions of political order.","translation":"这种现代、进步且和平的模式是独特的，并且优于其它所有现行的、针对政治秩序的根本性问题的众多模式。","targetForm":"superior","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Not a few people think that all foreign-made articles are superior to ones made in this country.","translation":"不少人认为，所有外国制造的物品均优于那些在本国所制造的。","targetForm":"superior","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The hearing acuity of dogs is superior by far to that of humans.","translation":"狗的听觉比人类灵敏不知多少倍。","targetForm":"superior","senseId":"source-n-2","sourceSenseId":"n-2"}]},"subject":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"主题"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"科目"}],"examples":[{"sentence":"Godwin's law teaches us that any infinite discussion about an arbitrary subject converges to a Nazi comparison.","translation":"高德温法则告诉我们对任何主题的所有无休止的讨论会趋于和纳粹主义的类比。","targetForm":"subject","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"We're studying English, which is an important subject these days.","translation":"我们学习英语，就今天来说是一项重要科目。","targetForm":"subject","senseId":"source-n-1","sourceSenseId":"n-1"}]},"supreme":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"至高"}],"examples":[{"sentence":"Finally, Trump will nominate conservative justices for the Supreme Court, which has had one vacancy since Justice Antonin Scalia died in February.","translation":"最后，特朗普将提名保守派法官进入最高法院，2月份安东宁·斯卡利亚（Antonin Scalia）法官逝世后，最高法院已经出现了一个空缺。","targetForm":"supreme","senseId":"source-n-1","sourceSenseId":"n-1"}]},"summer":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"夏季"}],"examples":[{"sentence":"Then came the news that Brazil will host the 2016 Summer Olympic Games – this coming on top of hosting the 2014 World Cup.","translation":"随后传来消息说2016年夏季奥运会将在巴西举办 — — 巴西也同样是2014年世界杯的主办国。","targetForm":"summer","senseId":"source-n-1","sourceSenseId":"n-1"}]},"suburb":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"郊区"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"市郊住宅区"}],"examples":[{"sentence":"She lived in the suburbs of Tokyo when she was young.","translation":"她年轻的时候住在东京的郊区。","targetForm":"suburbs","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"You need a car if you live in the suburbs.","translation":"要住在郊区的话，汽车是必需的。","targetForm":"suburbs","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Helen and Kathy rented an apartment in a suburb of Tokyo.","translation":"海伦和凯蒂在东京郊区租了个套间。","targetForm":"suburb","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A car is a must for life in the suburbs.","translation":"要住在郊区的话，汽车是必需的。","targetForm":"suburbs","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The other day something horrible happened in a Tokyo suburb.","translation":"前几天，东京郊外发生了件可怕的事情。","targetForm":"suburb","senseId":"source-n-2","sourceSenseId":"n-2"}]},"support":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"支持"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"援助"}],"examples":[{"sentence":"First, we will continue to support the institutions that helped get us to where we are now.","translation":"首先，我们将继续支持对实现当前目标做出贡献的机构。","targetForm":"support","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Eighth, some emerging-market economies with weaker economic fundamentals may not be able to avoid a severe financial crisis, despite massive IMF support.","translation":"第八，有些经济基本面薄弱的新兴经济体，尽管有国际货币基金组织的大力支持，可能仍然无法避免一场严重的金融危机。","targetForm":"support","senseId":"source-n-3","sourceSenseId":"n-3"}]},"summit":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"最高级会议"}],"examples":[{"sentence":"The Summit of the Americas thus serves as a bellwether of United States-Latin American relations, even if it fails to accomplish much of significance.","translation":"于是，美洲峰会就成了美国-拉美关系的风向标，尽管这个风向标有时并不怎么灵验。","targetForm":"summit","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Either way, the Seoul G-20 summit will likely mark a watershed in the history of the post-war global political economy.","translation":"无论会议结果如何，首尔的G-20峰会都将成为后二战时代全球政治经济历史的分水岭。","targetForm":"summit","senseId":"source-n-3","sourceSenseId":"n-3"}]},"sunshine":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"阳光"}],"examples":[{"sentence":"We all know that blue-eyed red-heads are sensitive to sunshine, burning more readily than dark-skinned people.","translation":"我们都知道，蓝眼睛红头发的人对阳光敏感，比深色皮肤的人更容易晒伤。","targetForm":"sunshine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Sunshine is a warm burst of joy after a gloomy, rainy week.","translation":"阴雨连绵的一周后，阳光让人感到一阵温暖喜悦。","targetForm":"sunshine","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"As food and drink is to animals, so are rain and sunshine to plants.","translation":"动物需要食物和饮料，而植物则需要雨水和阳光。","targetForm":"sunshine","senseId":"source-n-1","sourceSenseId":"n-1"}]},"suggestion":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"意见"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"提议"}],"examples":[{"sentence":"Government officials say there’s no evidence to support the suggestion that Chinese students may be the ones inadvertently spreading the virus.","translation":"政府官员表示，没有证据支撑中国学生可能是无意中传播病毒的人的观点。","targetForm":"suggestion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"We are open to all suggestions regarding the new design of the website.","translation":"关于网站的新设计，我们乐于接受任何建议。","targetForm":"suggestions","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"He thought she spoke reasonably, so he accepted her suggestion.","translation":"他觉得她说得很有道理，于是接受了她的建议。","targetForm":"suggestion","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
